// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D4: más de 5 registros duplicados en una tabla crítica. El SQL filtra los eventos ya alertados.
const filas = $input.all().map(i => i.json).filter(r => r.marca);
return filas.map(r => ({ json: {
  codigo: 'D4',
  severidad: 'ADVERTENCIA',
  tipo: 'Registros duplicados en tabla crítica',
  tabla: r.tabla,
  detalle: `${r.marca}. Umbral: 5. Criterio: ${r.criterio}. Ejemplos: ${r.ejemplos}`,
  query: r.tabla === 'clientes'
    ? 'SELECT correo, COUNT(*) FROM clientes GROUP BY correo HAVING COUNT(*) > 1;'
    : 'SELECT cliente_id, producto_id, cantidad, fecha, COUNT(*) FROM ventas GROUP BY 1, 2, 3, 4 HAVING COUNT(*) > 1;',
  usuario: 'N/A (revisar auditoria_datos: operacion INSERT)',
  accion: 'Depurar los duplicados y evaluar una restricción UNIQUE (por ejemplo en clientes.correo).'
}}));
